package main

import (
	"fmt"
	"time"
)

func main() {
	go func() {
		x := 0
		for i := 0; i < 200000000; i++ {
			x += i
		}
		fmt.Println("计算结束", x)
	}()
	time.Sleep(50 * time.Millisecond)
	fmt.Println("主 goroutine 没被计算循环卡住")
}

package main

import (
	"fmt"
	"runtime"
	"time"
)

func main() {
	fmt.Println("启动前:", runtime.NumGoroutine())
	ch := make(chan int)
	go func() {
		<-ch // 永远等不到值，这个 goroutine 就泄漏了
	}()
	time.Sleep(100 * time.Millisecond)
	fmt.Println("启动后:", runtime.NumGoroutine())
}

