package main

import (
	"fmt"
	"runtime"
	"sync"
)

func main() {
	var wg sync.WaitGroup
	for i := 0; i < 1000; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			runtime.Gosched() // 主动把 CPU 让给别的 goroutine
		}()
	}
	wg.Wait()
	fmt.Println("跑完了", runtime.NumGoroutine(), "个 goroutine")
}
